#include <nlohmann/json.hpp>

int main() {
    try {
        nlohmann::json j = {{"a/b", 1}, {"m~n", 2}};
        nlohmann::json flat = j.flatten();
        nlohmann::json unflattened = flat.unflatten();
        std::cout << "unflattened match: " << (j == unflattened ? "true" : "false") << std::endl;
    } catch (const std::exception& e) {
        std::cout << "EXCEPTION: " << e.what() << std::endl;
    }
    return 0;
}
